<template>
  <div class="demo-page">
    <header>
      <p class="demo-page__eyebrow">远程组件</p>
      <h1 class="demo-page__title">comps-vue3 · SplitCodePreview</h1>
      <p class="demo-page__lead">
        来自 video-code 的「分割线切换界面和代码」：左边用 Shadow DOM 把一段 HTML/CSS 实时渲染成界面，
        右边是同一段代码，中间一条发光的竖线可以左右拖 —— 拖到哪，界面就在哪里被裁开、代码从右边浮上来，
        交界处还有扫描线和一点色差。原 demo 的这段代码是写死的，组件里改成 <code>code</code> 传入、
        编辑后通过 <code>update:code</code> 抛回，所以既能当「界面 ↔ 代码」对照器，也能当个小型 playground。
      </p>
    </header>

    <section class="split-demo">
      <div class="split-demo__head">
        <h2 class="demo-page__section-title">拖动分割线 · 直接改代码</h2>
        <code class="split-demo__tag">split {{ Math.round(split) }}%</code>
      </div>
      <p class="demo-card__text">
        拖动中间的圆点（或点一下分割线后用 ← → 微调，Home / End 直接贴边）。右边代码是可编辑的，
        改完停手 180ms 会自动重新渲染到左边的 Shadow DOM 里 —— 试试把 <code>border-radius</code> 或者
        颜色改掉。脚本不会执行，只渲染 HTML / CSS。
      </p>

      <div class="split-demo__stage">
        <SplitCodePreview v-model:split="split" :code="code" @update:code="onCode" @change="onChange" />
      </div>

      <p class="split-demo__hint">
        最近一次渲染：<code>{{ changeCount }}</code> 次 · 分割线：<code>{{ Math.round(split) }}%</code>
      </p>

      <div class="split-demo__row">
        <div class="split-demo__cell">
          <SplitCodePreview
            :code="cardCode"
            :split="35"
            :glitch="0"
            :editable="false"
            :radius="10"
          />
          <p>只读 + 无扫描线（<code>glitch=0</code>），适合纯对照</p>
        </div>
        <div class="split-demo__cell">
          <SplitCodePreview
            :code="cardCode"
            :split="62"
            :glitch="1"
            accent="#ff8a5c"
            :radius="26"
            :editable="false"
          />
          <p>换主色 / 圆角，扫描线拉满（<code>glitch=1</code>）</p>
        </div>
      </div>
    </section>

    <DemoPreview class="split-preview">
      <LevaPlayground
        name="SplitCodePreview"
        :component="SplitCodePreview"
        :schema="SplitCodePreviewSchema"
        :presets="{ split: 57, glitch: 0.45 }"
        :stage-style="stageStyle"
      />
    </DemoPreview>

    <p class="demo-note">
      <span>
        面板里 <code>split</code> 是分割线位置（也能直接拖），<code>glitch</code> 是交界扫描线 / 色差强度，
        <code>radius</code> / <code>accent</code> 是面板圆角和主色，<code>minSplit</code> /
        <code>maxSplit</code> 限制能拖到的范围，<code>editable</code> 关掉就变成只读对照。
        <code>code</code> 是字符串控件，改它等于换一段预览。
      </span>
    </p>
  </div>
</template>

<script setup lang="ts">
import { ref } from 'vue'
import SplitCodePreviewSchema from '@melt-js/comps-vue3/src/components/SplitCodePreview.propsSchema.json'
import DemoPreview from '../components/DemoPreview.vue'
import LevaPlayground from '../components/LevaPlayground.vue'
import { remoteComponent } from '../configs/remote'

const SplitCodePreview = remoteComponent('SplitCodePreview')

const cardCode = `<style>
.card {
  width: 220px;
  padding: 22px;
  border-radius: 16px;
  font-family: system-ui, sans-serif;
  text-align: center;
  color: #eaf6ff;
  background: linear-gradient(150deg, #102a4a, #061726);
  border: 1px solid rgba(120, 200, 255, .22);
}
.title { margin: 0 0 6px; font-size: 15px; }
.text { margin: 0; font-size: 12px; color: rgba(190, 225, 255, .6); }
</style>
<div class="card">
  <p class="title">分割线两侧</p>
  <p class="text">左边是渲染结果，右边是源码</p>
</div>`

const code = ref(cardCode)
const split = ref(57)
const changeCount = ref(1)

const stageStyle = {
  display: 'block',
  height: '560px',
  padding: '0',
  background: '#eef6ff',
}

function onCode(next: string) {
  code.value = next
}

function onChange() {
  changeCount.value += 1
}
</script>

